const i = $json;

let arquivos = i.arquivos;
if (typeof arquivos === 'string') { try { arquivos = JSON.parse(arquivos); } catch(e) {} }
arquivos = Array.isArray(arquivos) ? arquivos : [];

const urls = arquivos.map(a => a?.url).filter(Boolean);
const firstUrl = urls[0] || '';

const midiaTipo = String(i.midia_tipo || '').toLowerCase();
const isVideo = midiaTipo === 'video';

const payload = {
  meta: {
    post_id: i.post_id,
    platform: 'instagram_story',
    idempotency_key: i.idempotency_key ? `${i.idempotency_key}:story` : `${i.post_id}:instagram_story`,
  },
  media: {
    type: isVideo ? 'video' : 'image',
    first_url: firstUrl,
    urls,
    count: urls.length,
  },
  content: {
    // Story normalmente não usa caption, mas deixo disponível
    caption: i.texto_instagram_facebook || '',
  },
  platform_config: {
    instagram_story: {
      media_type: 'STORIES',
      isVideo,
    }
  }
};

return { json: { ...i, arquivos, mediaUrl: firstUrl, mediaUrls: urls, isVideo, payload } };
